WITH filtered AS (SELECT *, INITCAP(TRIM(city)) city_title FROM suppliers WHERE city IN ('New York', 'Berlin', 'Singapore')), metrics AS (SELECT *, SUM(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_rating, COUNT(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_count_rating, MIN(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_rating, SUM(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_rating FROM filtered), cleaned AS (SELECT id, country, rating, city_title, running_sum_rating, running_min_rating, cumulative_rating, CONCAT(supplier_name, ' - ', city) supplier_name_city FROM metrics WHERE city IS NOT NULL), with_last AS (SELECT s.id, s.country, s.running_sum_rating, s.running_min_rating, s.cumulative_rating, s.supplier_name_city, top1.launch_date, top1.product_stock_qty FROM cleaned s LEFT JOIN LATERAL (SELECT c.launch_date, c.stock_qty AS product_stock_qty FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT CASE WHEN running_sum_rating >= 15.6 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_sum_rating_tier, country, SUM(cumulative_rating) FILTER (WHERE country = 'UK') AS uk_total_cumulative_rating, APPROX_PERCENTILE(running_sum_rating, 0.5) AS running_sum_rating_p50, COUNT(*) AS row_count, COUNT(DISTINCT country) AS distinct_countries, DENSE_RANK() OVER (PARTITION BY CASE WHEN running_sum_rating >= 15.6 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY SUM(cumulative_rating) FILTER (WHERE country = 'UK') DESC) AS uk_total_cumulative_rating_dense_rank FROM with_last GROUP BY running_sum_rating_tier, country
